export const ANALYTICS_CLIENT_PLATFORM_HEADER = "X-Agent-Native-Client-Platform";
export const ANALYTICS_CLIENT_PLATFORM_PROPERTY = "client_platform";
export const ANALYTICS_CLIENT_PLATFORM_BODY_FIELD = "__agentNativeClientPlatform";
export const ANALYTICS_CLIENT_PLATFORMS = [
    "web",
    "electron",
    "mobile",
];
export function normalizeAnalyticsClientPlatform(value) {
    return typeof value === "string" &&
        ANALYTICS_CLIENT_PLATFORMS.includes(value)
        ? value
        : undefined;
}
